/**
 * Vitest 全局 Mock 配置
 *
 * 用于测试环境中的全局 Mock 设置
 */


// Mock localStorage
const localStorageMock = {
  getItem: vi.fn(),
  setItem: vi.fn(),
  removeItem: vi.fn(),
  clear: vi.fn(),
  get length() { return 0 },
  key: vi.fn()
}

Object.defineProperty(window, 'localStorage', {
  value: localStorageMock
})

// Mock sessionStorage
const sessionStorageMock = {
  getItem: vi.fn(),
  setItem: vi.fn(),
  removeItem: vi.fn(),
  clear: vi.fn(),
  get length() { return 0 },
  key: vi.fn()
}

Object.defineProperty(window, 'sessionStorage', {
  value: sessionStorageMock
})

// Mock matchMedia
Object.defineProperty(window, 'matchMedia', {
  writable: true,
  value: vi.fn().mockImplementation((query: MediaQueryList | string) => ({
    matches: false,
    media: query,
    onchange: null,
    addListener: vi.fn(),
    removeListener: vi.fn(),
    addEventListener: vi.fn(),
    removeEventListener: vi.fn(),
    dispatchEvent: vi.fn(),
  })),
})

// Mock IntersectionObserver
// @ts-ignore - Vitest global mock
global.IntersectionObserver = vi.fn().mockImplementation(() => ({
  observe: vi.fn(),
  unobserve: vi.fn(),
  disconnect: vi.fn(),
}))

// Mock ResizeObserver
// @ts-ignore - Vitest global mock
global.ResizeObserver = vi.fn().mockImplementation(() => ({
  observe: vi.fn(),
  unobserve: vi.fn(),
  disconnect: vi.fn(),
}))

// Mock requestAnimationFrame
// @ts-ignore - Vitest global mock
global.requestAnimationFrame = (callback: FrameRequestCallback) => {
  return setTimeout(callback, 16) as unknown as number
}

// Mock cancelAnimationFrame
// @ts-ignore - Vitest global mock
global.cancelAnimationFrame = (id: number) => {
  clearTimeout(id)
}

/**
 * useResponsiveLayout.spec.ts
 * 响应式布局组合式函数测试
 * 
 * 测试覆盖：
 * 1. 断点检测逻辑
 * 2. 布局模式切换
 * 3. 面板状态管理
 * 4. localStorage持久化
 * 5. 触摸手势处理
 */

import { describe, it, expect, beforeEach, vi } from 'vitest'
import { ref } from 'vue'
import { useResponsiveLayout } from '../useResponsiveLayout'

// Mock localStorage
const localStorageMock = {
  getItem: vi.fn(),
  setItem: vi.fn(),
  removeItem: vi.fn(),
  clear: vi.fn(),
}

Object.defineProperty(window, 'localStorage', {
  value: localStorageMock,
})

// Mock useBreakpoints
vi.mock('../useBreakpoints', () => ({
  useBreakpoints: (_breakpoints: unknown) => ({
    isMobile: ref(false),
    isTablet: ref(false),
    isDesktop: ref(true),
    smaller: () => ref(false),
    greaterOrEqual: () => ref(true),
    between: () => ref(false),
  }),
}))

describe('useResponsiveLayout', () => {
  beforeEach(() => {
    // 清理mock
    localStorageMock.getItem.mockClear()
    localStorageMock.setItem.mockClear()
    localStorageMock.removeItem.mockClear()

    // 默认mock返回空对象（无存储设置）
    localStorageMock.getItem.mockReturnValue(null)
  })

  describe('初始化', () => {
    it('应该初始化为桌面模式', () => {
      const { layoutMode } = useResponsiveLayout()
      expect(layoutMode.value).toBe('desktop')
    })

    it('应该有默认的面板宽度', () => {
      const { leftPanel, rightPanel } = useResponsiveLayout()
      expect(leftPanel.value.width).toBe(280)
      expect(rightPanel.value.width).toBe(320)
    })

    it('默认激活编辑器tab', () => {
      const { activeTab } = useResponsiveLayout()
      expect(activeTab.value).toBe('editor')
    })
  })

  describe('布局模式切换', () => {
    it('应该正确识别移动端模式', () => {
      // 这里需要mock useBreakpoints返回isMobile=true
      // 由于模块已加载，实际测试中可能需要使用mockImplementation
      void 0 // Placeholder
    })

    it('应该正确识别平板模式', () => {
      // 类似上面的测试
    })

    it('应该正确识别桌面模式', () => {
      const { layoutMode } = useResponsiveLayout()
      expect(layoutMode.value).toBe('desktop')
    })
  })

  describe('面板状态管理', () => {
    it('左侧面板在桌面模式下应该是expanded', () => {
      const { leftPanel } = useResponsiveLayout()
      expect(leftPanel.value.state).toBe('expanded')
    })

    it('右侧面板在桌面模式下应该是expanded', () => {
      const { rightPanel } = useResponsiveLayout()
      expect(rightPanel.value.state).toBe('expanded')
    })

    it('应该可以切换面板折叠状态', () => {
      const { leftPanel, togglePanel } = useResponsiveLayout()

      expect(leftPanel.value.state).toBe('expanded')

      togglePanel('left')

      // 注意：由于leftPanel是computed，这里需要重新获取或使用nextTick
      // 实际测试中需要正确的响应式处理
    })

    it('应该可以更新面板宽度', () => {
      const { updatePanelWidth } = useResponsiveLayout()

      updatePanelWidth('left', 350)

      // 验证宽度已更新并保存到localStorage
      expect(localStorageMock.setItem).toHaveBeenCalled()
    })

    it('应该限制面板宽度在最小和最大值之间', () => {
      const { updatePanelWidth } = useResponsiveLayout()

      // 测试小于最小值
      updatePanelWidth('left', 150)
      expect(localStorageMock.setItem).toHaveBeenCalledWith(
        'editor-layout-settings',
        (expect as any).stringContaining('"leftPanelWidth":200')
      )

      // 测试大于最大值
      updatePanelWidth('left', 700)
      expect(localStorageMock.setItem).toHaveBeenCalledWith(
        'editor-layout-settings',
        (expect as any).stringContaining('"leftPanelWidth":600')
      )
    })
  })

  describe('localStorage持久化', () => {
    it('应该从localStorage加载保存的设置', () => {
      const savedSettings = {
        leftPanelWidth: 300,
        rightPanelWidth: 350,
        leftPanelCollapsed: false,
        rightPanelCollapsed: true,
      }

      localStorageMock.getItem.mockReturnValue(JSON.stringify(savedSettings))

      const { leftPanel, rightPanel } = useResponsiveLayout()

      expect(leftPanel.value.width).toBe(300)
      expect(rightPanel.value.width).toBe(350)
    })

    it('应该保存面板宽度到localStorage', () => {
      const { updatePanelWidth } = useResponsiveLayout()

      updatePanelWidth('left', 350)

      expect(localStorageMock.setItem).toHaveBeenCalledWith(
        'editor-layout-settings',
        (expect as any).stringContaining('"leftPanelWidth":350')
      )
    })

    it('应该保存面板折叠状态到localStorage', () => {
      const { togglePanel } = useResponsiveLayout()

      togglePanel('left')

      expect(localStorageMock.setItem).toHaveBeenCalledWith(
        'editor-layout-settings',
        (expect as any).stringContaining('"leftPanelCollapsed":true')
      )
    })

    it('应该处理localStorage异常', () => {
      localStorageMock.setItem.mockImplementation(() => {
        throw new Error('Storage quota exceeded')
      })

      const { updatePanelWidth } = useResponsiveLayout()

      // 不应该抛出错误
      expect(() => updatePanelWidth('left', 350)).not.toThrow()
    })

    it('应该处理JSON解析异常', () => {
      localStorageMock.getItem.mockReturnValue('invalid json')

      // 不应该抛出错误，应该返回默认设置
      const { leftPanel } = useResponsiveLayout()
      expect(leftPanel.value.width).toBe(280)
    })
  })

  describe('移动端tab切换', () => {
    it('应该可以切换到左侧面板tab', () => {
      const { activeTab, switchTab } = useResponsiveLayout()

      switchTab('left')
      expect(activeTab.value).toBe('left')
    })

    it('应该可以切换到右侧面板tab', () => {
      const { activeTab, switchTab } = useResponsiveLayout()

      switchTab('right')
      expect(activeTab.value).toBe('right')
    })

    it('应该可以切换到编辑器tab', () => {
      const { activeTab, switchTab } = useResponsiveLayout()

      activeTab.value = 'left'
      switchTab('editor')
      expect(activeTab.value).toBe('editor')
    })
  })

  describe('触摸手势处理', () => {
    it('左滑应该切换到下一个tab', () => {
      const { activeTab, handleTouchGesture } = useResponsiveLayout()

      activeTab.value = 'editor'
      handleTouchGesture('left')
      expect(activeTab.value).toBe('left')

      handleTouchGesture('left')
      expect(activeTab.value).toBe('right')
    })

    it('右滑应该切换到上一个tab', () => {
      const { activeTab, handleTouchGesture } = useResponsiveLayout()

      activeTab.value = 'right'
      handleTouchGesture('right')
      expect(activeTab.value).toBe('editor')
    })

    it('在第一个tab右滑不应该切换', () => {
      const { activeTab, handleTouchGesture } = useResponsiveLayout()

      activeTab.value = 'left'
      handleTouchGesture('right')
      expect(activeTab.value).toBe('left')
    })

    it('在最后一个tab左滑不应该切换', () => {
      const { activeTab, handleTouchGesture } = useResponsiveLayout()

      activeTab.value = 'right'
      handleTouchGesture('left')
      expect(activeTab.value).toBe('right')
    })

    it('在非移动模式下不应该响应手势', () => {
      const { activeTab, handleTouchGesture } = useResponsiveLayout()

      activeTab.value = 'editor'
      handleTouchGesture('left')

      // 桌面模式下不会改变tab
      expect(activeTab.value).toBe('editor')
    })
  })

  describe('重置布局', () => {
    it('应该重置所有设置到默认值', () => {
      const { activeTab, resetLayout } = useResponsiveLayout()

      // 修改一些设置
      activeTab.value = 'left'

      resetLayout()

      // 验证已重置
      // 注意：这里需要重新获取useResponsiveLayout实例
      // 实际测试中可能需要使用fresh实例
    })

    it('应该清除localStorage', () => {
      const { resetLayout } = useResponsiveLayout()

      resetLayout()

      expect(localStorageMock.removeItem).toHaveBeenCalledWith('editor-layout-settings')
    })
  })

  describe('布局配置对象', () => {
    it('应该返回完整的布局配置', () => {
      const { layout } = useResponsiveLayout()

      expect(layout.value).toHaveProperty('mode')
      expect(layout.value).toHaveProperty('leftPanel')
      expect(layout.value).toHaveProperty('rightPanel')
      expect(layout.value).toHaveProperty('activeTab')
    })

    it('面板配置应该包含所有必需属性', () => {
      const { leftPanel } = useResponsiveLayout()

      expect(leftPanel.value).toHaveProperty('position')
      expect(leftPanel.value).toHaveProperty('state')
      expect(leftPanel.value).toHaveProperty('width')
      expect(leftPanel.value).toHaveProperty('defaultWidth')
      expect(leftPanel.value).toHaveProperty('minWidth')
      expect(leftPanel.value).toHaveProperty('maxWidth')
      expect(leftPanel.value).toHaveProperty('visible')
    })

    it('移动端下面板visible应该根据activeTab变化', () => {
      // 这个测试需要mock useBreakpoints返回isMobile=true
    })
  })

  describe('边界情况', () => {
    it('应该处理空localStorage', () => {
      localStorageMock.getItem.mockReturnValue(null)

      const { leftPanel, rightPanel } = useResponsiveLayout()

      expect(leftPanel.value.width).toBe(280)
      expect(rightPanel.value.width).toBe(320)
    })

    it('应该处理部分缺失的存储设置', () => {
      localStorageMock.getItem.mockReturnValue(
        JSON.stringify({ leftPanelWidth: 300 })
      )

      const { leftPanel, rightPanel } = useResponsiveLayout()

      expect(leftPanel.value.width).toBe(300)
      expect(rightPanel.value.width).toBe(320) // 使用默认值
    })

    it('应该处理无效的面板宽度值', () => {
      localStorageMock.getItem.mockReturnValue(
        JSON.stringify({ leftPanelWidth: 'invalid' })
      )

      // 不应该抛出错误
      expect(() => {
        useResponsiveLayout()
      }).not.toThrow()
    })
  })
})

/**
 * 图形导出导入服务
 */

import type { DrawNode, DrawEdge } from './types'

/**
 * 导出/导入服务
 */
export class DrawExportService {
  /**
   * 导出为 JSON 文件内容
   */
  static async exportJSON(
    nodes: DrawNode[],
    edges: DrawEdge[],
    title: string = '未命名图表'
  ): Promise<string> {
    const data = {
      version: '1.0.0',
      exportedAt: new Date().toISOString(),
      title,
      nodes,
      edges
    }
    return JSON.stringify(data, null, 2)
  }

  /**
   * 从 JSON 导入
   */
  static async importJSON(jsonString: string): Promise<{
    nodes: DrawNode[]
    edges: DrawEdge[]
    title: string
  }> {
    try {
      const data = JSON.parse(jsonString)
      return {
        nodes: data.nodes || [],
        edges: data.edges || [],
        title: data.title || '导入的图表'
      }
    } catch (error) {
      throw new Error('JSON 格式错误')
    }
  }

  /**
   * 生成 Markdown 表格形式的节点列表
   */
  static generateNodeTable(nodes: DrawNode[]): string {
    let markdown = '| ID | 名称 | 描述 | 类型 |\n'
    markdown += '|-----|------|------|------|\n'

    nodes.forEach(node => {
      const desc = node.description?.replace(/\n/g, ' ') || '-'
      markdown += `| ${node.id.substring(0, 8)} | ${node.label} | ${desc} | ${node.type} |\n`
    })

    return markdown
  }

  /**
   * 生成 Markdown 关系列表
   */
  static generateRelationList(nodes: DrawNode[], edges: DrawEdge[]): string {
    if (edges.length === 0) return '暂无连接关系'

    let markdown = ''
    const nodeMap = new Map(nodes.map(n => [n.id, n]))

    edges.forEach(edge => {
      const fromNode = nodeMap.get(edge.fromNodeId)
      const toNode = nodeMap.get(edge.toNodeId)
      if (fromNode && toNode) {
        markdown += `- **${fromNode.label}** ${edge.label ? `(${edge.label})` : '->'} **${toNode.label}**\n`
      }
    })

    return markdown
  }

  /**
   * 导出为 Markdown 文件
   */
  static async exportMarkdown(
    nodes: DrawNode[],
    edges: DrawEdge[],
    title: string = '未命名图表',
    description: string = ''
  ): Promise<string> {
    let markdown = `# ${title}\n\n`

    if (description) {
      markdown += `${description}\n\n`
    }

    markdown += '## 概览\n\n'
    markdown += `- 节点总数：${nodes.length}\n`
    markdown += `- 连接总数：${edges.length}\n`
    markdown += `- 导出时间：${new Date().toLocaleString()}\n\n`

    markdown += '## 节点列表\n\n'
    markdown += this.generateNodeTable(nodes)
    markdown += '\n\n'

    markdown += '## 关系图\n\n'
    markdown += this.generateRelationList(nodes, edges)
    markdown += '\n\n'

    markdown += '## 详细信息\n\n'
    nodes.forEach(node => {
      markdown += `### ${node.label}\n\n`
      if (node.description) {
        markdown += `**描述:** ${node.description}\n\n`
      }
      markdown += `- **ID:** ${node.id}\n`
      markdown += `- **类型:** ${node.type}\n`
      markdown += `- **尺寸:** ${node.width} x ${node.height}\n`
      markdown += `- **位置:** (${node.x}, ${node.y})\n`
      markdown += `- **颜色:** ${node.color}\n`

      if (node.metadata && Object.keys(node.metadata).length > 0) {
        markdown += `- **元数据:**\n`
        Object.entries(node.metadata).forEach(([key, value]) => {
          markdown += `  - ${key}: ${JSON.stringify(value)}\n`
        })
      }
      markdown += '\n'
    })

    return markdown
  }

  /**
   * 导出为 CSV 格式
   */
  static async exportCSV(
    nodes: DrawNode[],
    edges: DrawEdge[]
  ): Promise<{ nodesCsv: string; edgesCsv: string }> {
    // 节点 CSV
    let nodesCsv = 'ID,名称,描述,类型,X,Y,宽,高,颜色,边框颜色\n'
    nodes.forEach(node => {
      const desc = (node.description || '').replace(/"/g, '""')
      nodesCsv += `"${node.id}","${node.label}","${desc}","${node.type}",${node.x},${node.y},${node.width},${node.height},"${node.color}","${node.borderColor}"\n`
    })

    // 连接 CSV
    let edgesCsv = '源节点ID,目标节点ID,标签,类型,颜色,线宽\n'
    edges.forEach(edge => {
      edgesCsv += `"${edge.fromNodeId}","${edge.toNodeId}","${edge.label || ''}","${edge.type}","${edge.color}",${edge.lineWidth}\n`
    })

    return { nodesCsv, edgesCsv }
  }

  /**
   * 从 CSV 导入节点
   */
  static async importNodesFromCSV(csvString: string): Promise<DrawNode[]> {
    const lines = csvString.trim().split('\n')
    const nodes: DrawNode[] = []

    // 跳过标题行
    for (let i = 1; i < lines.length; i++) {
      const line = lines[i]
      const values = this.parseCSVLine(line)

      if (values.length >= 10) {
        nodes.push({
          id: values[0],
          label: values[1],
          description: values[2],
          type: values[3] as any,
          x: parseFloat(values[4]),
          y: parseFloat(values[5]),
          width: parseFloat(values[6]),
          height: parseFloat(values[7]),
          color: values[8],
          borderColor: values[9]
        })
      }
    }

    return nodes
  }

  /**
   * 解析 CSV 行
   */
  private static parseCSVLine(line: string): string[] {
    const result: string[] = []
    let current = ''
    let inQuotes = false

    for (let i = 0; i < line.length; i++) {
      const char = line[i]

      if (char === '"') {
        if (inQuotes && line[i + 1] === '"') {
          current += '"'
          i++
        } else {
          inQuotes = !inQuotes
        }
      } else if (char === ',' && !inQuotes) {
        result.push(current)
        current = ''
      } else {
        current += char
      }
    }

    result.push(current)
    return result.map(v => v.replace(/^"|"$/g, ''))
  }

  /**
   * 生成下载链接
   */
  static createDownloadLink(content: string, _filename: string, mimeType: string = 'text/plain'): string {
    const blob = new Blob([content], { type: mimeType })
    return URL.createObjectURL(blob)
  }

  /**
   * 下载文件
   */
  static downloadFile(content: string, filename: string, mimeType: string = 'text/plain'): void {
    const link = document.createElement('a')
    link.href = this.createDownloadLink(content, filename, mimeType)
    link.download = filename
    link.click()
    URL.revokeObjectURL(link.href)
  }

  /**
   * 转换为 PlantUML 格式
   */
  static generatePlantUML(nodes: DrawNode[], edges: DrawEdge[]): string {
    let puml = '@startuml\n'
    puml += 'skinparam backgroundColor #FEFEFE\n'

    // 添加节点
    nodes.forEach(node => {
      if (node.type === 'group') {
        puml += `package "${node.label}" {\n}\n`
      } else {
        puml += `node "${node.label}" as ${node.id}\n`
      }
    })

    // 添加连接
    edges.forEach(edge => {
      puml += `${edge.fromNodeId} --> ${edge.toNodeId}\n`
    })

    puml += '@enduml\n'
    return puml
  }

  /**
   * 转换为 GraphViz DOT 格式
   */
  static generateGraphVizDOT(nodes: DrawNode[], edges: DrawEdge[], directed: boolean = true): string {
    const graphType = directed ? 'digraph' : 'graph'
    const edgeOp = directed ? '->' : '--'
    let dot = `${graphType} G {\n`
    dot += '  rankdir=LR;\n'
    dot += '  node [shape=box, style=rounded];\n'

    // 添加节点
    nodes.forEach(node => {
      const label = node.label.replace(/"/g, '\\"')
      dot += `  "${node.id}" [label="${label}"];\n`
    })

    // 添加连接
    edges.forEach(edge => {
      if (edge.label) {
        dot += `  "${edge.fromNodeId}" ${edgeOp} "${edge.toNodeId}" [label="${edge.label}"];\n`
      } else {
        dot += `  "${edge.fromNodeId}" ${edgeOp} "${edge.toNodeId}";\n`
      }
    })

    dot += '}\n'
    return dot
  }
}

/**
 * 辅助函数：获取文件扩展名
 */
export function getFileExtension(filename: string): string {
  return filename.split('.').pop()?.toLowerCase() || ''
}

/**
 * 辅助函数：验证文件类型
 */
export function validateFileType(filename: string, allowedTypes: string[]): boolean {
  const ext = getFileExtension(filename)
  return allowedTypes.includes(ext)
}

/**
 * 辅助函数：生成时间戳文件名
 */
export function generateTimestampFilename(prefix: string = 'export', ext: string = 'json'): string {
  const timestamp = new Date().toISOString().replace(/[:.]/g, '-')
  return `${prefix}_${timestamp}.${ext}`
}

export default DrawExportService


import { describe, it, expect, beforeEach, vi, afterEach } from 'vitest'
import { UnifiedWebSocketService } from '../unified-websocket.service'
import { WebSocketMessageType, WebSocketConnectionState } from '../../types/websocket.types'

// Create a mock WebSocket class
class MockWebSocket {
  static CONNECTING = 0
  static OPEN = 1
  static CLOSING = 2
  static CLOSED = 3

  send = vi.fn()
  close = vi.fn()
  readyState = MockWebSocket.CONNECTING

  private eventHandlers: Map<string, Array<Function>> = new Map()

  constructor(_url: string) {
    // Don't throw error in constructor
  }

  addEventListener(event: string, handler: Function) {
    if (!this.eventHandlers.has(event)) {
      this.eventHandlers.set(event, [])
    }
    this.eventHandlers.get(event)!.push(handler)
  }

  removeEventListener(event: string, handler: Function) {
    const handlers = this.eventHandlers.get(event)
    if (handlers) {
      const index = handlers.indexOf(handler)
      if (index > -1) {
        handlers.splice(index, 1)
      }
    }
  }

  // Helper method to trigger events
  triggerEvent(event: string, data?: unknown) {
    const handlers = this.eventHandlers.get(event) || []
    handlers.forEach(handler => handler(data))
  }
}

describe('UnifiedWebSocketService', () => {
  let service: UnifiedWebSocketService

  beforeEach(() => {
    // Mock global WebSocket with the class directly
    // @ts-ignore - Mocking global WebSocket
    global.WebSocket = MockWebSocket

    service = new UnifiedWebSocketService({
      url: 'ws://localhost:8080/ws',
      token: 'test-token',
      reconnectInterval: 1000,
      maxReconnectAttempts: 3,
    })
  })

  afterEach(() => {
    service.disconnect()
    vi.clearAllMocks()
  })

  it('should initialize with disconnected state', () => {
    expect(service.getState()).toBe(WebSocketConnectionState.DISCONNECTED)
  })

  it('should connect to websocket', async () => {
    await service.connect()

    // WebSocket should be created
    // @ts-ignore - Accessing private property for testing
    expect((service as any).ws).toBeInstanceOf(MockWebSocket)
  })

  it('should handle connection open', () => {
    const onConnect = vi.fn()

    service.on('connect', onConnect)
    service.connect()

    // Get mock instance and trigger open event
    // @ts-ignore - Accessing private property for testing
    const mockWsInstance = (service as any).ws as MockWebSocket
    mockWsInstance.triggerEvent('open')

    expect(service.getState()).toBe(WebSocketConnectionState.CONNECTED)
    expect(onConnect).toHaveBeenCalled()
  })

  it('should handle incoming messages', () => {
    const onMessage = vi.fn()

    service.on('message', onMessage)
    service.connect()

    const testData = {
      type: WebSocketMessageType.MESSAGE,
      data: { text: 'hello' },
      timestamp: Date.now(),
    }

    // Get mock instance and trigger message event
    // @ts-ignore - Accessing private property for testing
    const mockWsInstance = (service as any).ws as MockWebSocket
    mockWsInstance.triggerEvent('message', { data: JSON.stringify(testData) })

    expect(onMessage).toHaveBeenCalledWith(testData)
  })

  it('should not reconnect when max attempts reached', async () => {
    vi.useFakeTimers()

    service.connect()

    // Helper function to get current WebSocket instance and trigger error
    const triggerError = () => {
      // @ts-ignore - Accessing private property for testing
      const mockWsInstance = (service as any).ws as MockWebSocket
      mockWsInstance.triggerEvent('error', new Error('Connection failed'))
    }

    // Simulate 3 connection failures
    triggerError()
    vi.advanceTimersByTime(1000)

    triggerError()
    vi.advanceTimersByTime(1000)

    triggerError()
    vi.advanceTimersByTime(1000)

    // After 3 failed attempts, state should be ERROR
    expect(service.getState()).toBe(WebSocketConnectionState.ERROR)

    vi.useRealTimers()
  })

  it('should send messages', () => {
    service.connect()

    // Get mock instance and simulate connection opened
    // @ts-ignore - Accessing private property for testing
    const mockWsInstance = (service as any).ws as MockWebSocket
    mockWsInstance.readyState = MockWebSocket.OPEN
    mockWsInstance.triggerEvent('open')

    service.send({
      type: WebSocketMessageType.MESSAGE,
      data: { text: 'test' },
    })

    expect(mockWsInstance.send).toHaveBeenCalled()
  })
})

/**
 * Storage Service
 * Abstraction layer for browser storage (localStorage and sessionStorage)
 */

export interface StorageOptions {
  type?: 'local' | 'session'
  ttl?: number // Time to live in milliseconds
}

interface StorageItem<T> {
  value: T
  expires?: number
}

class StorageService {
  /**
   * Set item in storage
   */
  public set<T>(key: string, value: T, options: StorageOptions = {}): void {
    const { type = 'local', ttl } = options
    const storage = type === 'local' ? localStorage : sessionStorage

    const item: StorageItem<T> = {
      value,
      expires: ttl ? Date.now() + ttl : undefined
    }

    try {
      storage.setItem(key, JSON.stringify(item))
    } catch (error) {
      console.error(`Failed to set item in ${type} storage:`, error)
    }
  }

  /**
   * Get item from storage
   */
  public get<T>(key: string, options: StorageOptions = {}): T | null {
    const { type = 'local' } = options
    const storage = type === 'local' ? localStorage : sessionStorage

    try {
      const itemStr = storage.getItem(key)
      if (!itemStr) {
        return null
      }

      const item: StorageItem<T> = JSON.parse(itemStr)

      // Check if item has expired
      if (item.expires && Date.now() > item.expires) {
        this.remove(key, options)
        return null
      }

      return item.value
    } catch (error) {
      console.error(`Failed to get item from ${type} storage:`, error)
      return null
    }
  }

  /**
   * Remove item from storage
   */
  public remove(key: string, options: StorageOptions = {}): void {
    const { type = 'local' } = options
    const storage = type === 'local' ? localStorage : sessionStorage

    try {
      storage.removeItem(key)
    } catch (error) {
      console.error(`Failed to remove item from ${type} storage:`, error)
    }
  }

  /**
   * Clear all items from storage
   */
  public clear(options: StorageOptions = {}): void {
    const { type = 'local' } = options
    const storage = type === 'local' ? localStorage : sessionStorage

    try {
      storage.clear()
    } catch (error) {
      console.error(`Failed to clear ${type} storage:`, error)
    }
  }

  /**
   * Check if key exists in storage
   */
  public has(key: string, options: StorageOptions = {}): boolean {
    const { type = 'local' } = options
    const storage = type === 'local' ? localStorage : sessionStorage

    return storage.getItem(key) !== null
  }

  /**
   * Get all keys from storage
   */
  public keys(options: StorageOptions = {}): string[] {
    const { type = 'local' } = options
    const storage = type === 'local' ? localStorage : sessionStorage

    return Object.keys(storage)
  }

  /**
   * Get storage size in bytes
   */
  public getSize(options: StorageOptions = {}): number {
    const { type = 'local' } = options
    const storage = type === 'local' ? localStorage : sessionStorage

    let size = 0
    for (const key in storage) {
      if (storage.hasOwnProperty(key)) {
        size += key.length + (storage.getItem(key)?.length || 0)
      }
    }

    return size
  }

  /**
   * Clean up expired items
   */
  public cleanExpired(options: StorageOptions = {}): void {
    const { type = 'local' } = options
    const storage = type === 'local' ? localStorage : sessionStorage

    const keysToRemove: string[] = []

    for (let i = 0; i < storage.length; i++) {
      const key = storage.key(i)
      if (key) {
        try {
          const itemStr = storage.getItem(key)
          if (itemStr) {
            const item: StorageItem<any> = JSON.parse(itemStr)
            if (item.expires && Date.now() > item.expires) {
              keysToRemove.push(key)
            }
          }
        } catch (error) {
          // Invalid JSON, remove it
          keysToRemove.push(key)
        }
      }
    }

    keysToRemove.forEach(key => storage.removeItem(key))
  }
}

// Export singleton instance
export const storageService = new StorageService()

export default storageService

