// 9. BeforeClose - 关闭前回调
export const BeforeClose: Story = {
  render: () => ({
    components: { Drawer, Button },
    setup() {
      const visible = ref(false)
      const loading = ref(false)
      const hasChanges = ref(true)

      const beforeClose = async () => {
        if (!hasChanges.value) {
          return true
        }

        loading.value = true
        // 模拟异步操作
        await new Promise(resolve => setTimeout(resolve, 500))
        loading.value = false

        // 可以在这里添加保存逻辑或提示用户
        const confirmed = confirm('您有未保存的更改，确定要关闭吗？')
        return confirmed
      }

      return { visible, loading, beforeClose, hasChanges }
    },
    template: `
      <div class="p-8">
        <div class="mb-4">
          <label class="flex items-center gap-2">
            <input
              type="checkbox"
              v-model="hasChanges"
              class="rounded border-neutral-300"
            />
            <span class="text-sm text-neutral-600 dark:text-neutral-400">
              模拟有未保存的更改
            </span>
          </label>
        </div>
        <Button @click="visible = true">打开带验证的抽屉</Button>
        <Drawer
          title="关闭前验证"
          :before-close="beforeClose"
          v-model="visible"
        >
          <div class="space-y-4">
            <p class="text-neutral-600 dark:text-neutral-400">
              尝试关闭这个抽屉时会触发验证操作。
            </p>
            <p v-if="hasChanges" class="text-amber-600 dark:text-amber-400 text-sm">
              当前有未保存的更改
            </p>
            <p v-if="loading" class="text-primary-600 dark:text-primary-400 text-sm">
              正在验证...
            </p>
          </div>
        </Drawer>
      </div>
    `,
  }),
}

