      expect(wrapper.vm.sourceData).toHaveLength(newData.length)
    })
  })

  // 边界情况测试
  describe('边界情况', () => {
    it('应该处理空数据', () => {
      const wrapper = mount(Transfer, {
        props: {
          data: [],
          modelValue: [],
        },
      })

      expect(wrapper.vm.sourceData).toHaveLength(0)
      expect(wrapper.vm.targetData).toHaveLength(0)
    })

    it('应该处理空 modelValue', () => {
