   */
  formatWithdrawalStatus(status: string): string {
    const statusMap: Record<string, string> = {
      pending: '待处理',
      approved: '已批准',
      rejected: '已拒绝',
      completed: '已完成',
    }
    return statusMap[status] || status
  }
}

