<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'
import { message, messageBox } from '@/design-system/services'
import {
  Plus,
  Picture,
  CircleCheck,
  View,
  Refresh,
  Reading,
  FolderOpened,
  Link,
  Edit,
  Delete,
} from '@element-plus/icons-vue'
import { getBanners, createBanner, updateBanner, deleteBanner } from '../api'

// 筛选器
const filters = reactive({
  targetType: '',
  status: '',
})

// 分页
const pagination = reactive({
  page: 1,
  pageSize: 10,
})

// 统计数据
const stats = reactive({
  total: 0,
  active: 0,
  totalClicks: 0,
})

// 数据
const loading = ref(false)
const banners = ref<any[]>([])
const total = ref(0)
const dialogVisible = ref(false)
const editingBanner = ref<any | null>(null)
const submitting = ref(false)

const bannerForm = reactive({
  title: '',
  description: '',
  image: '',
  target: '',
  targetType: 'book',
  sortOrder: 0,
  isActive: true,
})

// 加载Banner列表
const loadBanners = async () => {
  loading.value = true
  try {
    const response = await getBanners({
      page: pagination.page,
      pageSize: pagination.pageSize,
      targetType: filters.targetType || undefined,
      status: filters.status || undefined,
    })
    banners.value = response.items
    total.value = response.total || 0
    stats.total = total.value
    stats.active = response.items.filter((banner) => banner.isActive).length
    stats.totalClicks = response.items.reduce(
      (sum, banner) => sum + Number(banner.clickCount || 0),
      0,
    )
  } catch (error) {
    console.error('加载Banner列表失败:', error)
    banners.value = []
    total.value = 0
    stats.total = 0
    stats.active = 0
    stats.totalClicks = 0
    message.error('加载Banner列表失败')
  } finally {
    loading.value = false
  }
}

// 筛选变化
const handleFilterChange = () => {
  pagination.page = 1
  loadBanners()
}

const getTypeLabel = (type: string): string => {
  const labels: Record<string, string> = {
    book: '书籍',
    category: '分类',
    url: '外链',
  }
  return labels[type] || type
}

const handleCreate = () => {
  editingBanner.value = null
  Object.assign(bannerForm, {
    title: '',
    description: '',
    image: '',
    target: '',
    targetType: 'book',
    sortOrder: 0,
    isActive: true,
  })
  dialogVisible.value = true
}

const handleEdit = (banner: any) => {
  editingBanner.value = banner
  Object.assign(bannerForm, {
    title: banner.title,
    description: banner.description,
    image: banner.image,
    target: banner.target,
    targetType: banner.targetType,
    sortOrder: banner.sortOrder,
    isActive: banner.isActive,
  })
  dialogVisible.value = true
}

const handleSubmit = async () => {
  if (!bannerForm.title || !bannerForm.image || !bannerForm.target) {
    message.warning('请填写必填项')
    return
  }

  submitting.value = true
  try {
    if (editingBanner.value) {
      await updateBanner(editingBanner.value.id, bannerForm)
      message.success('更新成功')
    } else {
      await createBanner(bannerForm)
      message.success('创建成功')
    }
    dialogVisible.value = false
    void loadBanners()
  } catch (error) {
    message.error('操作失败')
  } finally {
    submitting.value = false
  }
}

const handleStatusChange = async (banner: any) => {
  try {
    await updateBanner(banner.id, { isActive: banner.isActive })
    message.success(banner.isActive ? '已启用' : '已禁用')
    void loadBanners()
  } catch (error) {
    message.error('状态更新失败')
    banner.isActive = !banner.isActive
  }
}

const handleDelete = async (banner: any) => {
  try {
    await messageBox.confirm('确定要删除此Banner吗？', '确认', {
      type: 'warning',
    })

    await deleteBanner(banner.id)

    message.success('删除成功')
    void loadBanners()
  } catch (error: any) {
    if (error !== 'cancel') {
      message.error('删除失败')
    }
  }
}

onMounted(() => {
  void loadBanners()
})
</script>

