      )
    },
    methods: {
      // 添加 focus 方法以支持组件测试中的 tagInputRef.value?.focus() 调用
      focus() {
        // Mock implementation
      }
    }
  })

  const MockQyButton = defineComponent({
    name: 'QyButton',
    props: {
      variant: { type: String, default: 'default' },
      size: { type: String, default: 'medium' },
      disabled: { type: Boolean, default: false },
      loading: { type: Boolean, default: false },
      type: { type: String, default: 'button' },
    },
    emits: ['click'],
    setup(props: any, { emit, slots }: any) {
      const classes = [
        'qy-button',
        `qy-button--${props.variant}`,
        `qy-button--${props.size}`,
      ]
      if (props.disabled) classes.push('is-disabled')
      if (props.loading) classes.push('is-loading')

      return () => h(
        'button',
        {
          class: classes,
          disabled: props.disabled,
          type: props.type,
          onClick: (e: any) => emit('click', e),
        },
        slots.default ? slots.default() : []
      )
    },
  })

  const MockQyBadge = defineComponent({
    name: 'QyBadge',
    props: {
      variant: { type: String, default: 'default' },
      size: { type: String, default: 'medium' },
      closable: { type: Boolean, default: false },
    },
    emits: ['click', 'close'],
    setup(props: any, { emit, slots }: any) {
      const children = [
        slots.default ? slots.default() : '',
      ]
      if (props.closable) {
        children.push(
          h('span', {
            class: 'close-btn',
            onClick: (e: any) => {
              e.stopPropagation()
              emit('close')
            },
          }, '×')
        )
      }
      return () => h(
        'span',
        {
          class: ['qy-badge', `qy-badge--${props.variant}`, `qy-badge--${props.size}`],
          onClick: () => emit('click'),
        },
        children
      )
    },
  })

  const MockQyIcon = defineComponent({
    name: 'QyIcon',
    props: {
      name: { type: String, required: true },
      size: { type: Number, default: 16 },
    },
    setup(props: any) {
      return () => h('i', { class: `qy-icon qy-icon--${props.name}`, style: { fontSize: `${props.size}px` } })
    },
  })

  return {
    QyInput: MockQyInput,
    QyButton: MockQyButton,
    QyBadge: MockQyBadge,
    QyIcon: MockQyIcon,
  }
})

