    it('应该跳过空行', async () => {
      const mockNDJSON = `{"type":"meta","cursor":"abc","total":0,"hasMore":false}

{"type":"done","cursor":"def","total":0,"hasMore":false}`

      global.fetch = vi.fn().mockResolvedValue({
        ok: true,
        body: {
          getReader: vi.fn().mockReturnValue({
            read: vi.fn()
