        ok: false,
        status: 404
      })

      await expect(
        streamBookstoreService.streamSearchBooks('test')
      ).rejects.toThrow('HTTP error! status: 404')
    })

    it('应该处理流式error类型消息', async () => {
      const errorNDJSON = `{"type":"error","error":"Invalid keyword"}`

