import httpService from '@/core/services/http.service'
import type {
  Timeline,
  TimelineEvent,
  SaveTimelineRequest,
  SaveTimelineEventRequest,
} from '../types/timeline'

// 假设后端路由配置如下 (根据 Gin Handler 推断):
// POST   /api/v1/projects/:projectId/timelines
// GET    /api/v1/projects/:projectId/timelines
// GET    /api/v1/timelines/:timelineId?projectId=...
// DELETE /api/v1/timelines/:timelineId?projectId=...
//
// POST   /api/v1/timelines/:timelineId/events?projectId=...
// GET    /api/v1/timelines/:timelineId/events
// GET    /api/v1/events/:eventId?projectId=...
// PUT    /api/v1/events/:eventId?projectId=...
// DELETE /api/v1/events/:eventId?projectId=...
// GET    /api/v1/timelines/:timelineId/visualization

const BASE_PROJECT_URL = '/writer/projects'
const BASE_TIMELINE_URL = '/timelines'
const BASE_EVENT_URL = '/events' // 假设独立事件操作在根 /events 路由下

export const timelineApi = {
  // ==========================================
  // 时间线管理 (Timeline CRUD)
  // ==========================================

  /**
   * 创建时间线
   * POST /api/v1/projects/{projectId}/timelines
   */
  create(projectId: string, data: SaveTimelineRequest) {
    return httpService.post<Timeline>(`${BASE_PROJECT_URL}/${projectId}/timelines`, data)
  },

  /**
   * 获取项目时间线列表
   * GET /api/v1/projects/{projectId}/timelines
   */
  list(projectId: string) {
    return httpService.get<Timeline[]>(`${BASE_PROJECT_URL}/${projectId}/timelines`)
  },

  /**
   * 获取时间线详情
   * GET /api/v1/timelines/{timelineId}?projectId=...
   */
  getDetail(timelineId: string, projectId: string) {
    return httpService.get<Timeline>(
      `${BASE_TIMELINE_URL}/${timelineId}`,
      { params: { projectId } } as any
    )
  },

  /**
   * 删除时间线
   * DELETE /api/v1/timelines/{timelineId}?projectId=...
   */
  delete(timelineId: string, projectId: string) {
    return httpService.delete<void>(
      `${BASE_TIMELINE_URL}/${timelineId}`,
      { params: { projectId } } as any
    )
  },

  /**
   * 获取时间线可视化数据
   * GET /api/v1/timelines/{timelineId}/visualization
   * 返回类型可能是复杂的图表数据，暂时用 any 或定义专门的 Visualization 类型
   */
  getVisualization(timelineId: string) {
    return httpService.get<any>(`${BASE_TIMELINE_URL}/${timelineId}/visualization`)
  },

  // ==========================================
  // 事件管理 (Event CRUD)
  // ==========================================

  /**
   * 创建时间线事件
   * POST /api/v1/timelines/{timelineId}/events?projectId=...
   * 注意：后端要求 query 中带 projectId
   */
  createEvent(timelineId: string, projectId: string, data: SaveTimelineEventRequest) {
    return httpService.post<TimelineEvent>(
      `${BASE_TIMELINE_URL}/${timelineId}/events`,
      data,
      { params: { projectId } } // POST 请求中 Query 参数需放在 config.params
    )
  },

  /**
   * 获取时间线事件列表
   * GET /api/v1/timelines/{timelineId}/events
   */
  listEvents(timelineId: string) {
    return httpService.get<TimelineEvent[]>(`${BASE_TIMELINE_URL}/${timelineId}/events`)
  },

  /**
   * 获取事件详情
   * GET /api/v1/events/{eventId}?projectId=...
   */
  getEvent(eventId: string, projectId: string) {
    return httpService.get<TimelineEvent>(`${BASE_EVENT_URL}/${eventId}`, { params: { projectId } })
  },

  /**
   * 更新事件
   * PUT /api/v1/events/{eventId}?projectId=...
   */
  updateEvent(eventId: string, projectId: string, data: SaveTimelineEventRequest) {
    return httpService.put<TimelineEvent>(`${BASE_EVENT_URL}/${eventId}`, data, {
      params: { projectId },
    })
  },

  /**
   * 删除事件
   * DELETE /api/v1/events/{eventId}?projectId=...
   */
  deleteEvent(eventId: string, projectId: string) {
    return httpService.delete<void>(`${BASE_EVENT_URL}/${eventId}`, { params: { projectId } })
  },
}

// 便捷函数导出（兼容旧代码）
export const listTimelines = (projectId: string) => timelineApi.list(projectId)
export const listTimelineEvents = (timelineId: string, _projectId?: string) => timelineApi.listEvents(timelineId)

/**
 * usePanelResize 组合式函数测试
 *
 * 测试面板调整大小功能：
 * 1. 拖拽开始/结束逻辑
 * 2. 宽度计算正确
 * 3. 宽度约束（200-600px）
 * 4. panelStore状态更新
 * 5. 事件监听器清理
 */

import { describe, it, expect, beforeEach, vi, afterEach } from 'vitest'
import { createPinia, setActivePinia } from 'pinia'
import { usePanelResize } from '../usePanelResize'
import { usePanelStore } from '@/modules/writer/stores/panelStore'

describe('usePanelResize', () => {
  let pinia: ReturnType<typeof createPinia>

  beforeEach(() => {
    pinia = createPinia()
    setActivePinia(pinia)
    // 清除localStorage
    localStorage.clear()
    // Mock localStorage
    const localStorageMock = (() => {
      let store: Record<string, string> = {}
      return {
        getItem: (key: string) => store[key] || null,
        setItem: (key: string, value: string) => { store[key] = String(value) },
        removeItem: (key: string) => { delete store[key] },
        clear: () => { store = {} }
      }
    })()
    vi.stubGlobal('localStorage', localStorageMock)
  })

  afterEach(() => {
    vi.clearAllMocks()
  })

  describe('初始化', () => {
    it('应该初始化响应式宽度', () => {
      const { currentWidth } = usePanelResize({
        panelId: 'left',
        defaultWidth: 280,
        minWidth: 200,
        maxWidth: 600
      })

      expect(currentWidth.value).toBe(280)
    })

    it('应该使用正确的默认宽度', () => {
      const { currentWidth } = usePanelResize({
        panelId: 'right',
        defaultWidth: 320,
        minWidth: 200,
        maxWidth: 600
      })

      expect(currentWidth.value).toBe(320)
    })

    it('应该从panelStore加载保存的宽度', () => {
      // 预设localStorage
      localStorage.setItem('qingyu_editor_panel_layout', JSON.stringify({
        leftWidth: 350,
        rightWidth: 400,
        rightCollapsed: false
      }))

      const { currentWidth } = usePanelResize({
        panelId: 'left',
        defaultWidth: 280,
        minWidth: 200,
        maxWidth: 600
      })

      expect(currentWidth.value).toBe(350)
    })

    it('应该初始化为非拖拽状态', () => {
      const { isDragging } = usePanelResize({
        panelId: 'left',
        defaultWidth: 280,
        minWidth: 200,
        maxWidth: 600
      })

      expect(isDragging.value).toBe(false)
    })
  })

  describe('拖拽开始', () => {
    it('应该设置拖拽状态为true', () => {
      const { isDragging, startDrag } = usePanelResize({
        panelId: 'left',
        defaultWidth: 280,
        minWidth: 200,
        maxWidth: 600
      })

      startDrag({
        position: 'left',
        startX: 100,
        startY: 0
      })

      expect(isDragging.value).toBe(true)
    })

    it('应该记录拖拽起始位置', () => {
      const { startDrag } = usePanelResize({
        panelId: 'left',
        defaultWidth: 280,
        minWidth: 200,
        maxWidth: 600
      })

      startDrag({
        position: 'left',
        startX: 100,
        startY: 0
      })

      // 内部状态应该记录起始位置
      // 这个测试需要通过行为验证
    })

    it('应该记录拖拽起始宽度', () => {
      const { startDrag } = usePanelResize({
        panelId: 'left',
        defaultWidth: 280,
        minWidth: 200,
        maxWidth: 600
      })

      startDrag({
        position: 'left',
        startX: 100,
        startY: 0
      })

      // 内部状态应该记录起始宽度
      // 这个测试需要通过行为验证
    })
  })

  describe('宽度计算', () => {
    it('左侧面板向右拖拽应该增加宽度', () => {
      const { currentWidth, startDrag, onDrag } = usePanelResize({
        panelId: 'left',
        defaultWidth: 280,
        minWidth: 200,
        maxWidth: 600
      })

      startDrag({
        position: 'left',
        startX: 100,
        startY: 0
      })

      // 向右拖拽50px
      onDrag({ clientX: 150, clientY: 0 } as MouseEvent)

      // 新宽度 = 280 + (150 - 100) = 330
      expect(currentWidth.value).toBe(330)
    })

    it('左侧面板向左拖拽应该减少宽度', () => {
      const { currentWidth, startDrag, onDrag } = usePanelResize({
        panelId: 'left',
        defaultWidth: 280,
        minWidth: 200,
        maxWidth: 600
      })

      startDrag({
        position: 'left',
        startX: 100,
        startY: 0
      })

      // 向左拖拽30px
      onDrag({ clientX: 70, clientY: 0 } as MouseEvent)

      // 新宽度 = 280 + (70 - 100) = 250
      expect(currentWidth.value).toBe(250)
    })

    it('右侧面板向左拖拽应该增加宽度', () => {
      const { currentWidth, startDrag, onDrag } = usePanelResize({
        panelId: 'right',
        defaultWidth: 320,
        minWidth: 200,
        maxWidth: 600
      })

      startDrag({
        position: 'right',
        startX: 500,
        startY: 0
      })

      // 向左拖拽50px
      onDrag({ clientX: 450, clientY: 0 } as MouseEvent)

      // 新宽度 = 320 + (500 - 450) = 370
      expect(currentWidth.value).toBe(370)
    })

    it('右侧面板向右拖拽应该减少宽度', () => {
      const { currentWidth, startDrag, onDrag } = usePanelResize({
        panelId: 'right',
        defaultWidth: 320,
        minWidth: 200,
        maxWidth: 600
      })

      startDrag({
        position: 'right',
        startX: 500,
        startY: 0
      })

      // 向右拖拽30px
      onDrag({ clientX: 530, clientY: 0 } as MouseEvent)

      // 新宽度 = 320 + (500 - 530) = 290
      expect(currentWidth.value).toBe(290)
    })
  })

  describe('宽度约束', () => {
    it('应该限制最小宽度为200px', () => {
      const { currentWidth, startDrag, onDrag } = usePanelResize({
        panelId: 'left',
        defaultWidth: 250,
        minWidth: 200,
        maxWidth: 600
      })

      startDrag({
        position: 'left',
        startX: 100,
        startY: 0
      })

      // 尝试向左拖拽超过最小宽度
      onDrag({ clientX: -100, clientY: 0 } as MouseEvent)

      // 宽度应该被限制在200px
      expect(currentWidth.value).toBe(200)
    })

    it('应该限制最大宽度为600px', () => {
      const { currentWidth, startDrag, onDrag } = usePanelResize({
        panelId: 'left',
        defaultWidth: 500,
        minWidth: 200,
        maxWidth: 600
      })

      startDrag({
        position: 'left',
        startX: 100,
        startY: 0
      })

      // 尝试向右拖拽超过最大宽度
      onDrag({ clientX: 300, clientY: 0 } as MouseEvent)

      // 宽度应该被限制在600px
      expect(currentWidth.value).toBe(600)
    })

    it('应该使用自定义的minWidth', () => {
      const { currentWidth, startDrag, onDrag } = usePanelResize({
        panelId: 'left',
        defaultWidth: 300,
        minWidth: 250,
        maxWidth: 600
      })

      startDrag({
        position: 'left',
        startX: 100,
        startY: 0
      })

      // 尝试向左拖拽超过自定义最小宽度
      onDrag({ clientX: -100, clientY: 0 } as MouseEvent)

      // 宽度应该被限制在250px
      expect(currentWidth.value).toBe(250)
    })

    it('应该使用自定义的maxWidth', () => {
      const { currentWidth, startDrag, onDrag } = usePanelResize({
        panelId: 'left',
        defaultWidth: 450,
        minWidth: 200,
        maxWidth: 500
      })

      startDrag({
        position: 'left',
        startX: 100,
        startY: 0
      })

      // 尝试向右拖拽超过自定义最大宽度
      onDrag({ clientX: 200, clientY: 0 } as MouseEvent)

      // 宽度应该被限制在500px
      expect(currentWidth.value).toBe(500)
    })

    it('在约束范围内应该正常工作', () => {
      const { currentWidth, startDrag, onDrag } = usePanelResize({
        panelId: 'left',
        defaultWidth: 300,
        minWidth: 200,
        maxWidth: 600
      })

      startDrag({
        position: 'left',
        startX: 100,
        startY: 0
      })

      // 在约束范围内拖拽
      onDrag({ clientX: 150, clientY: 0 } as MouseEvent)

      // 宽度应该正常更新
      expect(currentWidth.value).toBe(350)
    })
  })

  describe('panelStore集成', () => {
    it('应该更新panelStore的leftWidth', () => {
      const store = usePanelStore()

      const { startDrag, onDrag, stopDrag } = usePanelResize({
        panelId: 'left',
        defaultWidth: 280,
        minWidth: 200,
        maxWidth: 600
      })

      startDrag({
        position: 'left',
        startX: 100,
        startY: 0
      })

      onDrag({ clientX: 150, clientY: 0 } as MouseEvent)

      stopDrag()

      // 验证panelStore已更新
      expect(store.leftWidth).toBe(330)
    })

    it('应该更新panelStore的rightWidth', () => {
      const store = usePanelStore()

      const { startDrag, onDrag, stopDrag } = usePanelResize({
        panelId: 'right',
        defaultWidth: 320,
        minWidth: 200,
        maxWidth: 600
      })

      startDrag({
        position: 'right',
        startX: 500,
        startY: 0
      })

      onDrag({ clientX: 450, clientY: 0 } as MouseEvent)

      stopDrag()

      // 验证panelStore已更新
