          '黑衣骑手们越来越近，马蹄声如雷鸣般震撼着整个村庄。李明能感受到村民们惊恐的目光，但他没有退缩。',
          '"站住！"李明大喝一声，挡在了村口。',
          '为首的黑衣人冷笑一声："小子，让开，别找死！"',
        ]

        // 模拟章节内容
        chapterContent.value = {
          chapter: currentChapter.value,
          content: mockParagraphs.join('\n\n'),
          paragraphs: mockParagraphs.map((content, index) => ({
            id: `mock-paragraph-${index + 1}`,
            paragraphOrder: index + 1,
            content,
            format: 'markdown',
            wordCount: content.length,
          })),
          nextChapter: {
            id: 'chapter-002',
            bookId: 'test-book-001',
            chapterNumber: 2,
            title: '第二章：意外相遇',
            wordCount: 2800,
          } as any,
          prevChapter: null,
        } as any

        readingProgress.value = 0

        // 模拟网络延迟
        await new Promise((resolve) => setTimeout(resolve, 500))

        return { chapter: currentChapter.value, content: chapterContent.value }
      }

      // 生产模式：调用真实API
      const [chapterRes, contentRes] = await Promise.all([
        readerAPI.getChapterInfo(chapterId),
        readerAPI.getChapterContent(currentBookId.value || '', chapterId),
      ])

      // 合并章节信息和内容数据，并转换字段名
      const chapterInfo = (chapterRes as any)?.data ?? (chapterRes as any)
      const contentData = (contentRes as any)?.data ?? (contentRes as any)
      const previousBookId = currentBookId.value

      // 转换API响应数据格式为前端Chapter类型
      // 后端返回 hasNext/hasPrevious 布尔值，前端需要兼容使用
      const chapter: any = {
        id: chapterInfo.id ?? chapterInfo.chapterId,
        bookId: chapterInfo.book_id ?? chapterInfo.bookId ?? currentBookId.value,
        title: chapterInfo.title,
        chapterNumber: chapterInfo.chapter_num ?? chapterInfo.chapterNum,
        wordCount: chapterInfo.word_count ?? chapterInfo.wordCount,
        isFree: chapterInfo.is_free ?? chapterInfo.isFree,
        price: chapterInfo.price,
        publishedAt: chapterInfo.publish_time ?? chapterInfo.publishTime ?? chapterInfo.publishedAt,
        createdAt: chapterInfo.created_at ?? chapterInfo.createdAt,
        updatedAt: chapterInfo.updated_at ?? chapterInfo.updatedAt,
        // 导航ID优先从章节数据获取，否则使用后端返回的布尔标志
        prevChapterId: chapterInfo.prev_chapter_id ?? chapterInfo.prevChapterId ?? null,
        nextChapterId: chapterInfo.next_chapter_id ?? chapterInfo.nextChapterId ?? null,
        // 后端API返回的导航布尔标志
        hasPrevious: chapterInfo.hasPrevious ?? contentData.hasPrevious ?? false,
        hasNext: chapterInfo.hasNext ?? contentData.hasNext ?? false,
        content: contentData.content || '',
        paragraphs: Array.isArray(contentData.paragraphs) ? contentData.paragraphs : [],
      }

      if (chapter.bookId) {
        setCurrentBookId(chapter.bookId)
      }

      currentChapter.value = chapter
      chapterContent.value = chapter
      readingProgress.value = 0

      const needsNavigationPatch =
        !chapter.prevChapterId && !chapter.nextChapterId && !chapter.hasPrevious && !chapter.hasNext

      if (chapter.bookId && (chapterList.value.length === 0 || previousBookId !== chapter.bookId)) {
        await loadChapterList(chapter.bookId)
      }

      if (needsNavigationPatch || chapterList.value.length > 0) {
        patchChapterNavigation(chapter.id)
      }

      return { chapter: currentChapter.value, content: chapterContent.value }
    } catch (error) {
      console.error('加载章节失败:', error)
      throw error
    } finally {
      isLoading.value = false
    }
  }

  /**
   * 跳转到下一章
   */
  async function nextChapter() {
    if (!currentChapter.value?.nextChapterId) {
      throw new Error('没有下一章')
    }

    // 保存当前阅读进度
    await saveReadingProgress()

    return loadChapter(currentChapter.value.nextChapterId)
  }

  /**
   * 跳转到上一章
   */
  async function prevChapter() {
    if (!currentChapter.value?.prevChapterId) {
      throw new Error('没有上一章')
    }

    // 保存当前阅读进度
    await saveReadingProgress()

    return loadChapter(currentChapter.value.prevChapterId)
  }

  /**
   * 加载章节列表
   */
  async function loadChapterList(bookId: string) {
    try {
      // 检测测试模式
      const authStore = useAuthStore()
      const token = authStore.token as any
      const isMockToken =
        token && (typeof token === 'string' ? token : JSON.stringify(token)).includes('mock')

      if (isMockToken) {
        // 测试模式：使用模拟数据
        console.log('[测试模式] 加载章节列表:', bookId)

        const mockChapters = [
          { id: 'chapter-001', chapterNumber: 1, title: '第一章：初入江湖', wordCount: 2500 },
          { id: 'chapter-002', chapterNumber: 2, title: '第二章：意外相遇', wordCount: 2800 },
          { id: 'chapter-003', chapterNumber: 3, title: '第三章：危机四伏', wordCount: 3000 },
          { id: 'chapter-004', chapterNumber: 4, title: '第四章：绝地反击', wordCount: 3200 },
          { id: 'chapter-005', chapterNumber: 5, title: '第五章：真相大白', wordCount: 3500 },
        ]

        chapterList.value = mockChapters as any
        return mockChapters
      }

      // 生产模式：调用真实API
      const response = await readerAPI.getBookChapters(bookId)
      const rawList = Array.isArray(response)
        ? response
        : Array.isArray((response as any)?.data)
          ? (response as any).data
          : (response as any)?.data?.chapters || (response as any)?.chapters || []
      const normalized = normalizeChapterList(rawList as any[])
      chapterList.value = normalized as any
      if (bookId) {
        setCurrentBookId(bookId)
      }
      if (currentChapter.value?.id) {
        patchChapterNavigation(currentChapter.value.id)
      }
      return normalized
    } catch (error) {
      console.error('加载章节列表失败:', error)
      chapterList.value = []
      return []
    }
  }

  /**
   * 获取阅读设置
   */
  async function loadSettings() {
    try {
      // 检测测试模式
      const authStore = useAuthStore()
      const token = authStore.token as any
      const isMockToken =
        token && (typeof token === 'string' ? token : JSON.stringify(token)).includes('mock')

      if (isMockToken) {
        // 测试模式：使用默认设置，不调用API
        console.log('[测试模式] 使用默认阅读设置')
        return settings.value
      }

      // 生产模式：调用真实API
      const res = await readerAPI.getSettings()
      const data = res.data as any
      settings.value = { ...settings.value, ...data }
      return data
    } catch (error) {
      console.error('获取阅读设置失败:', error)
      // 继续使用默认设置
      return settings.value
    }
  }

  /**
   * 更新阅读设置
   */
  async function updateSettings(newSettings: Partial<ReaderSettings>) {
    try {
      settings.value = { ...settings.value, ...newSettings }

      // 检测测试模式
      const authStore = useAuthStore()
      const token = authStore.token as any
      const isMockToken =
        token && (typeof token === 'string' ? token : JSON.stringify(token)).includes('mock')

      if (isMockToken) {
        // 测试模式：仅本地更新，不调用API
        console.log('[测试模式] 更新阅读设置（仅本地）')
        return settings.value
      }

      // 生产模式：调用真实API
      const res = await readerAPI.updateSettings(newSettings as any)
      return res.data as any
    } catch (error) {
      console.error('更新阅读设置失败:', error)
      // 仍然保持本地更新
      return settings.value
    }
  }

  /**
   * 重置阅读设置
   */
  function resetSettings() {
    settings.value = getDefaultSettings()
  }

  /**
   * 保存阅读进度
   */
  async function saveReadingProgress() {
    if (!currentChapter.value) {
      return
    }

    try {
      // 检测测试模式
      const authStore = useAuthStore()
      const token = authStore.token as any
      const isMockToken =
        token && (typeof token === 'string' ? token : JSON.stringify(token)).includes('mock')

      if (isMockToken) {
        // 测试模式：仅本地保存，不调用API
        console.log('[测试模式] 保存阅读进度（仅本地）')
        return
      }

      // 生产模式：调用真实API
      await readerAPI.saveProgress({
        bookId: currentChapter.value.bookId,
        chapterId: currentChapter.value.id,
        progress: Math.max(0, Math.min(1, readingProgress.value / 100)),
      } as any)
    } catch (error) {
      console.error('保存阅读进度失败:', error)
      // 不抛出错误，避免影响阅读体验
    }
  }

  /**
   * 保存进度（带位置信息）
   */
  async function saveProgress(
    bookId: string,
    chapterId: string,
    progress: number,
    _scrollPosition: number,
  ) {
    try {
      // 检测测试模式
      const authStore = useAuthStore()
      const token = authStore.token as any
      const isMockToken =
        token && (typeof token === 'string' ? token : JSON.stringify(token)).includes('mock')

      if (isMockToken) {
        // 测试模式：仅本地保存，不调用API
        console.log('[测试模式] 保存进度（仅本地）')
        return
      }

      // 生产模式：调用真实API
      await readerAPI.saveProgress({
        bookId,
        chapterId,
        progress: Math.max(0, Math.min(1, progress / 100)),
      } as any)
    } catch (error) {
      console.error('保存进度失败:', error)
    }
  }

  /**
   * 更新阅读时长
   */
  async function updateReadingTime(bookId: string, duration: number) {
    try {
      // 这里可以调用相应的API更新阅读时长
      console.log('更新阅读时长:', bookId, duration)
    } catch (error) {
      console.error('更新阅读时长失败:', error)
    }
  }

  /**
   * 更新阅读进度
   */
  function updateProgress(progress: number) {
    readingProgress.value = Math.max(0, Math.min(100, progress))
  }

  /**
   * 跳转到上一章（别名）
   */
  async function loadPreviousChapter() {
    return prevChapter()
  }

  /**
   * 跳转到下一章（别名）
   */
  async function loadNextChapter() {
    return nextChapter()
  }

  /**
   * 获取默认设置
   */
  function getDefaultSettings(): ReaderSettings {
    return {
      userId: '',
      fontSize: 16,
      fontFamily: 'system-ui',
      lineHeight: 1.8,
      letterSpacing: 0,
      theme: 'light',
      pageMode: 'scroll',
      autoSave: true,
      enableAnimation: true,
      showProgress: true,
      pageWidth: 800,
      updatedAt: new Date().toISOString(),
    }
  }

  /**
   * 清除当前章节
   */
  function clearChapter() {
    currentChapter.value = null
    chapterContent.value = null
    readingProgress.value = 0
  }

  /**
   * 清除当前章节（别名）
   */
  function clearCurrentChapter() {
    clearChapter()
  }

  return {
    // 状态
    currentBookId,
    setCurrentBookId,
    currentChapter,
    chapterContent,
    chapterList,
    settings,
    isLoading,
    readingProgress,

    // 计算属性
    hasNextChapter,
    hasPrevChapter,

    // 方法
    loadChapter,
    nextChapter,
    prevChapter,
    loadPreviousChapter,
    loadNextChapter,
    loadChapterList,
    loadSettings,
    updateSettings,
    resetSettings,
    saveReadingProgress,
    saveProgress,
    updateReadingTime,
    updateProgress,
    clearChapter,
    clearCurrentChapter,
  }
})

/**
 * 社交功能状态管理
 */
import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import type { FollowStats } from '@/types/social'
import { followAPI } from '@/modules/social/api/follow'

export const useSocialStore = defineStore('social', () => {
  // 状态
  const followStats = ref<Map<string, FollowStats>>(new Map())
  const followingList = ref<Set<string>>(new Set())
  const followerList = ref<Set<string>>(new Set())
  const isLoading = ref(false)

  // Getters
  const isFollowing = computed(() => (userId: string) => {
    return followingList.value.has(userId)
  })

  const isFollower = computed(() => (userId: string) => {
    return followerList.value.has(userId)
  })

  const isMutualFollow = computed(() => (userId: string) => {
    return followingList.value.has(userId) && followerList.value.has(userId)
  })

  const getStats = computed(() => (userId: string) => {
    return followStats.value.get(userId)
  })

  // Actions
  async function fetchFollowStats(userId: string) {
    try {
      const response = await followAPI.getFollowStats(userId)
      followStats.value.set(userId, response as unknown as FollowStats)
    } catch (error) {
      console.error('[SocialStore] 获取关注统计失败:', error)
    }
  }

  async function followUser(userId: string) {
    isLoading.value = true
    try {
      await followAPI.followUser(userId)
      // 更新本地状态
      followingList.value.add(userId)

      // 更新统计
      const stats = followStats.value.get(userId)
      if (stats) {
        stats.followingCount++
      }
    } finally {
      isLoading.value = false
    }
  }

  async function unfollowUser(userId: string) {
    isLoading.value = true
    try {
      await followAPI.unfollowUser(userId)
      // 更新本地状态
      followingList.value.delete(userId)

      // 更新统计
      const stats = followStats.value.get(userId)
      if (stats) {
        stats.followingCount--
      }
    } finally {
      isLoading.value = false
    }
  }

  async function checkFollowStatus(userId: string) {
    try {
      const response = await followAPI.checkFollowStatus(userId)
      const { is_following } = response as unknown as { is_following: boolean }

      if (is_following) {
        followingList.value.add(userId)
      } else {
        followingList.value.delete(userId)
      }
    } catch (error) {
      console.error('[SocialStore] 检查关注状态失败:', error)
    }
  }

  async function fetchFollowingList(userId: string, page = 1, pageSize = 20) {
    try {
      const response = await followAPI.getFollowingList({ user_id: userId, page, page_size: pageSize })
      const data = response as unknown as { items: { user_id: string }[] }
      if (data?.items) {
        // 更新关注列表
        data.items.forEach((item: { user_id: string }) => {
          if (item.user_id) {
            followingList.value.add(item.user_id)
          }
        })

        return response
      }
    } catch (error) {
      console.error('[SocialStore] 获取关注列表失败:', error)
      throw error
    }
  }

  async function fetchFollowersList(userId: string, page = 1, pageSize = 20) {
    try {
      const response = await followAPI.getFollowersList({ user_id: userId, page, page_size: pageSize })
      const data = response as unknown as { items: { user_id: string }[] }
      if (data?.items) {
        // 更新粉丝列表
        data.items.forEach((item: { user_id: string }) => {
          if (item.user_id) {
            followerList.value.add(item.user_id)
          }
        })

        return response
      }
    } catch (error) {
      console.error('[SocialStore] 获取粉丝列表失败:', error)
      throw error
    }
  }

  // 批量操作
  async function batchFollow(userIds: string[]) {
    const results: { success: string[]; failed: string[] } = {
      success: [],
      failed: []
    }

    for (const userId of userIds) {
      try {
        await followUser(userId)
        results.success.push(userId)
      } catch (error) {
        results.failed.push(userId)
      }
    }

    return results
  }

  // 清除缓存
  function clearCache() {
    followStats.value.clear()
    followingList.value.clear()
    followerList.value.clear()
  }

  // 清除特定用户的缓存
  function clearUserCache(userId: string) {
    followStats.value.delete(userId)
    followingList.value.delete(userId)
    followerList.value.delete(userId)
  }

  return {
    // State
    followStats,
    followingList,
    followerList,
    isLoading,

    // Getters
    isFollowing,
    isFollower,
    isMutualFollow,
    getStats,

    // Actions
    fetchFollowStats,
    followUser,
    unfollowUser,
    checkFollowStatus,
    fetchFollowingList,
    fetchFollowersList,
    batchFollow,
    clearCache,
    clearUserCache
  }
})

