// --- 请求去重 + 缓存 组合工具 ---

class RequestDeduplicator {
  private pending = new Map<string, Promise<any>>()

  async deduplicate<T>(key: string, fn: () => Promise<T>): Promise<T> {
    if (this.pending.has(key)) {
      return this.pending.get(key) as Promise<T>
    }
    const promise = fn().finally(() => this.pending.delete(key))
    this.pending.set(key, promise)
    return promise
  }
}
const deduplicator = new RequestDeduplicator()

/**
 * 终极请求包装器：缓存 + 防抖
 * 
 * 解决了"缓存击穿"问题：当缓存失效时，多个并发请求只会有一个真正发给后端，
 * 其他请求会等待这第一个请求的结果。
 */
export async function cacheRequest<T>(
  key: string,
  requestFn: () => Promise<T>,
  options: {
    cache?: CacheManager
    expiresIn?: number
    forceRefresh?: boolean
    useDeduplication?: boolean // 是否开启去重
  } = {}
): Promise<T> {
  const { 
    cache = apiCache, 
    expiresIn, 
    forceRefresh = false,
    useDeduplication = true 
  } = options

  // 1. 查缓存
  if (!forceRefresh) {
    const cached = cache.get<T>(key)
    if (cached !== null) return cached
  }

  // 2. 定义实际请求逻辑（含写入缓存）
  const executeRequest = async () => {
    const data = await requestFn()
    cache.set(key, data, expiresIn)
    return data
  }

  // 3. 去重执行 或 直接执行
  if (useDeduplication) {
    // 使用去重器，key 需要包含特定的前缀以防冲突
    return deduplicator.deduplicate<T>(`req:${key}`, executeRequest)
  } else {
    return executeRequest()
  }
}

/**
 * HTML清理工具 - 防止XSS攻击
 * 使用DOMPurify清理HTML内容，确保用户输入的内容安全
 */

// @ts-ignore - DOMPurify使用CommonJS导出
import DOMPurify from 'dompurify'

/**
 * DOMPurify配置选项
 */
interface SanitizeConfig {
  /**
   * 允许的HTML标签
   * 默认允许基本的文本格式化标签
   */
  ALLOWED_TAGS?: string[]

  /**
   * 允许的HTML属性
   * 默认只允许安全的属性
   */
  ALLOWED_ATTR?: string[]

  /**
   * 是否允许使用data:协议的URL
   * 默认为false（更安全）
   */
  ALLOW_DATA_ATTR?: boolean

  /**
   * 是否允许使用SVG标签
   * 默认为false（更安全）
   */
  USE_PROFILES?: {
    svg?: boolean
    svgFilters?: boolean
    mathMl?: boolean
    html?: boolean
  }
}

/**
 * 默认配置 - 允许基本的文本格式化
 */
const DEFAULT_CONFIG: SanitizeConfig = {
